/bin/bash -lc "sleep 20; python - <<'PY'
import bioblend.galaxy, os, requests, time, json
key=open(os.environ['GALAXY_API_KEY_FILE']).read().strip()
base='https://usegalaxy.org'
gi=bioblend.galaxy.GalaxyInstance(url=base, key=key)
hist='bbd44e69cb8906b55e1a435e70c44d84'
assoc='fd7be06e1344d921'
def get_json(url):
    for attempt in range(8):
        r=requests.get(base+url, headers={'x-api-key':key})
        if r.status_code==200:
            try: return r.json()
            except Exception as e: print('bad json', r.status_code, r.text[:200])
        else:
            print('status', r.status_code, r.text[:200])
        time.sleep(10+attempt*5)
    raise RuntimeError('get failed')
a=get_json(f'/api/histories/{hist}/contents/dataset_collections/{assoc}')
arr=get_json(a['contents_url'])
ids=[e['object']['id'] for e in arr]
print('ids',len(ids))
remaining=[]
for i, ds in enumerate(ids):
    d=get_json(f'/api/histories/{hist}/contents/{ds}')
    if d.get('file_ext')"'!='"'fasta': remaining.append((i,ds))
print('remaining',len(remaining))
for n,(i,ds) in enumerate(remaining):
    success=False
    for attempt in range(10):
        try:
            gi.histories.update_dataset(hist, ds, datatype='fasta')
            success=True
            break
        except Exception as e:
            s=str(e)
            print('attempt fail', i, ds, s[:100])
            time.sleep(8+attempt*5)
    if not success: print('COULD NOT UPDATE', i, ds)
    if (n+1)%50==0: print('updated', n+1)
print('finished updates')
bad=0
for i, ds in enumerate(ids):
    d=get_json(f'/api/histories/{hist}/contents/{ds}')
    if d.get('file_ext')"'!='"'fasta': bad+=1
print('bad',bad)
PY"

